# We need to find x[0]...x[8] where each x[i] is an integer between 0 and 9
# and x[i] = count of i in the sequence.
# Also x[4] = 0.

# Let's use brute force search since the search space is manageable.
# Each x[i] is 0..9, but sum of all x[i] must be 9 (since there are 9 positions).
# Also, sum of i*x[i] must be 9 (since each position contributes 1 to the count of its value).

# Let's brute force with constraints.

def check(seq):
    for i in range(9):
        if seq.count(i) != seq[i]:
            return False
    return True

